let waChatState={chats:[],selected:'',limit:50,lastList:0,wasConnected:false},waConnectionBusy=false,waListBusy=false,waMessageBusy=false,waRestoreAttempted=false;
const waDrafts=new Map(),waSendRequests=new Map(),waSendingChats=new Set();
const waPhotos=new Map(),waPhotoPending=new Set();let waPhotoQueue=[],waPhotoWorkers=0,waPhotoObserver;
let waChatFilter='all';
const waSvg=(name)=>{const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/>',send:'<path d="m3 3 19 9-19 9 4-9-4-9Zm4 9h15"/>',person:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',group:'<circle cx="9" cy="8" r="3"/><path d="M2 22v-3a7 7 0 0 1 14 0v3M17 5a3 3 0 0 1 0 6m2 4a6 6 0 0 1 3 5"/>',back:'<path d="m14 5-7 7 7 7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.person)+'</svg>'};
function waAvatar(c){return '<span class="wa-chat-avatar">'+waSvg(c.isGroup?'group':'person')+'<img data-wa-photo="'+esc(c.id)+'" alt="'+esc(c.name)+' profile photo" loading="lazy" referrerpolicy="no-referrer" hidden></span>'}
function waApplyPhoto(id,url){$$('[data-wa-photo]').filter(img=>img.dataset.waPhoto===id).forEach(img=>{if(!url)return;img.onerror=()=>{img.hidden=true};img.src=url;img.hidden=false})}
function waQueuePhoto(id){const cached=waPhotos.get(id);if(cached&&cached.until>Date.now()){waApplyPhoto(id,cached.url);return}if(waPhotoPending.has(id))return;waPhotoPending.add(id);waPhotoQueue.push(id);waPumpPhotos()}
function waPumpPhotos(){while(waPhotoWorkers<3&&waPhotoQueue.length){const id=waPhotoQueue.shift();waPhotoWorkers++;api('/whatsapp/chats/photo?chatId='+encodeURIComponent(id)).then(result=>{waPhotos.set(id,{url:result.url,until:Date.now()+(result.url?600000:60000)});waApplyPhoto(id,result.url)}).catch(()=>{}).finally(()=>{waPhotoPending.delete(id);waPhotoWorkers--;waPumpPhotos()})}}
function waHydratePhotos(){waPhotoObserver?.disconnect();waPhotoObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){waQueuePhoto(entry.target.querySelector('img').dataset.waPhoto);waPhotoObserver.unobserve(entry.target)}}),{rootMargin:'150px'});$$('[data-wa-photo]').forEach(img=>{const cached=waPhotos.get(img.dataset.waPhoto);if(cached&&cached.until>Date.now())waApplyPhoto(img.dataset.waPhoto,cached.url);else waPhotoObserver.observe(img.parentElement)})}
function waTime(ts){return ts?new Date(ts*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):''}
function waChatDate(ts){if(!ts)return '';const day=new Date(ts*1000),today=new Date();return day.toDateString()===today.toDateString()?waTime(ts):day.toLocaleDateString([],{day:'2-digit',month:'2-digit',year:'2-digit'})}
async function whatsappChatsPage(){waRestoreAttempted=false;$('#view').innerHTML='<div class="wa-workspace"><section class="wa-sidebar"><div class="wa-list-heading"><h2>Chats</h2><button class="wa-icon-button" id="wa-refresh-all" title="Refresh chats" aria-label="Refresh chats">'+waSvg('refresh')+'</button></div><label class="wa-search-label">'+waSvg('search')+'<input id="wa-chat-search" placeholder="Search or start a new chat" aria-label="Search recent chats" autocomplete="off"></label><div class="wa-filters"><button data-wa-filter="all" class="active">All</button><button data-wa-filter="unread">Unread</button><button data-wa-filter="groups">Groups</button></div><div id="wa-live-connection" class="wa-live-connection">Connecting...</div><div id="wa-chat-list" class="wa-chat-list"><p>Loading your conversations...</p></div></section><section id="wa-thread" class="wa-thread"><div class="wa-welcome"><div class="wa-welcome-art"><svg viewBox="0 0 240 160" fill="none" aria-hidden="true"><rect x="36" y="20" width="168" height="112" rx="9" fill="#fff" stroke="#cad4d6" stroke-width="4"/><path d="M18 135h204l-14 12H32z" fill="#cad4d6"/><rect x="59" y="42" width="90" height="24" rx="7" fill="#d9fdd3"/><rect x="91" y="80" width="90" height="24" rx="7" fill="#e9edef"/><path d="m70 54 9 8 17-20" stroke="#00a884" stroke-width="3"/></svg></div><h2>WhatsApp for your store</h2><p>Send and receive messages from your linked phone.<br>Select a chat to get started.</p><small>'+waSvg('lock')+' Your conversations stay private to your store</small></div></section></div>';$('#wa-chat-search').oninput=waDrawChatList;$('#wa-refresh-all').onclick=async()=>{waPhotos.clear();await waRefreshConnection(false,true)};$$('[data-wa-filter]').forEach(b=>b.onclick=()=>{waChatFilter=b.dataset.waFilter;$$('[data-wa-filter]').forEach(x=>x.classList.toggle('active',x===b));waDrawChatList()});await waRefreshConnection(true,true)}
async function waRefreshConnection(restore=false,force=false){if(waConnectionBusy||view!=='whatsapp')return;waConnectionBusy=true;try{const status=await api('/whatsapp/status');if(view!=='whatsapp')return;const s=status.web;waDrawConnection(s);if(s.status==='disconnected'&&s.canRestore&&restore&&!waRestoreAttempted){waRestoreAttempted=true;await api('/whatsapp/web/start','POST',{});return}if(s.status==='connected'){if(force||!waChatState.wasConnected||Date.now()-waChatState.lastList>15000)await waLoadChatList();waChatState.wasConnected=true;if(waChatState.selected)await waLoadMessages(false)}else{waChatState.wasConnected=false;if($('#wa-send-text'))$('#wa-send-text').disabled=true;if($('#wa-send-button'))$('#wa-send-button').disabled=true}}catch(e){if($('#wa-live-connection'))$('#wa-live-connection').textContent=e.message}finally{waConnectionBusy=false}}
function waDrawConnection(s){const connected=s.status==='connected',pending=['starting','authenticating'].includes(s.status);$('#wa-live-connection').innerHTML='<span class="wa-connection-dot '+(connected?'connected':'')+'"></span>'+esc(connected?'Connected':pending?'Syncing WhatsApp...':'WhatsApp disconnected')+(!connected&&!pending?' <button class="wa-reconnect" id="wa-return-login">Reconnect</button>':'');if($('#wa-return-login'))$('#wa-return-login').onclick=()=>signOut();}
async function waLoadChatList(){if(waListBusy)return;waListBusy=true;try{const result=await api('/whatsapp/chats');if(view!=='whatsapp')return;waChatState.chats=result.chats;waChatState.lastList=Date.now();waDrawChatList()}catch(e){if($('#wa-chat-list'))$('#wa-chat-list').textContent=e.message}finally{waListBusy=false}}
function waDrawChatList(){const savedScroll=$('#wa-chat-list').scrollTop;const search=($('#wa-chat-search')?.value||'').toLowerCase(),chats=waChatState.chats.filter(c=>(c.name+' '+c.id.split('@')[0]).toLowerCase().includes(search)&&(waChatFilter==='all'||waChatFilter==='unread'&&c.unread>0||waChatFilter==='groups'&&c.isGroup));$('#wa-chat-list').innerHTML=chats.map(c=>'<button class="wa-chat '+(waChatState.selected===c.id?'active':'')+'" data-wa-chat="'+esc(c.id)+'">'+waAvatar(c)+'<span class="wa-chat-summary"><span class="wa-chat-title"><b>'+esc(c.name)+'</b><time class="'+(c.unread?'unread':'')+'">'+esc(waChatDate(c.timestamp))+'</time></span><span class="wa-chat-preview"><small>'+(c.lastMessage?.fromMe?'<span class="wa-preview-check">'+waReceipt(c.lastMessage)+'</span>':'')+esc(c.lastMessage?.text||c.lastMessage?.type||'Conversation')+'</small>'+(c.unread?'<span class="wa-unread">'+c.unread+'</span>':'')+'</span></span></button>').join('')||'<p class="wa-empty-list">No conversations found.</p>';$('#wa-chat-list').scrollTop=savedScroll;$$('[data-wa-chat]').forEach(b=>b.onclick=()=>waOpenChat(b.dataset.waChat));waHydratePhotos()}
function waReceipt(m){return m.ack===null||m.ack===undefined?'':m.ack>=2?'<span class="wa-receipt '+(m.ack>=3?'read':'')+'">&#10003;&#10003;</span>':m.ack===1?'<span class="wa-receipt">&#10003;</span>':'<span class="wa-receipt">&#9719;</span>'}
async function waOpenChat(id){const c=waChatState.chats.find(c=>c.id===id);if(!c)return;waChatState.selected=id;waChatState.limit=50;waDrawChatList();const readOnly=c.isGroup||c.isReadOnly;$('#wa-thread').innerHTML=`<div class="wa-thread-heading"><button class="wa-icon-button wa-mobile-back" id="wa-chat-back" aria-label="Back to chats">${waSvg('back')}</button>${waAvatar(c)}<div class="wa-contact-info"><h3>${esc(c.name)}</h3><small>${c.isGroup?'Group - view only':esc(c.id.split('@')[0])}</small></div><button class="btn small secondary" id="wa-more-messages">Load up to 100</button></div><div class="wa-messages" id="wa-message-list"><p>Loading messages...</p></div><form id="wa-reply-form" class="wa-reply-form"><label for="wa-send-text">${readOnly?'This conversation is view-only':'Reply to this conversation'}</label><div class="wa-compose"><textarea id="wa-send-text" maxlength="4000" required placeholder="Type a message" aria-label="Type a message" ${readOnly?'disabled':''}>${esc(waDrafts.get(id)||'')}</textarea><button class="btn" id="wa-send-button" ${readOnly?'disabled':''} aria-label="Send message">${waSvg('send')}</button></div><small>Enter to send. Shift + Enter for a new line.</small></form>`;$('.wa-workspace').classList.add('wa-chat-open');$('#wa-chat-back').onclick=()=>$('.wa-workspace').classList.remove('wa-chat-open');waHydratePhotos();$('#wa-send-text').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#wa-reply-form').requestSubmit()}};$('#wa-more-messages').onclick=async()=>{waChatState.limit=100;await waLoadMessages(false)};$('#wa-send-text').oninput=e=>waDrafts.set(id,e.target.value);$('#wa-reply-form').onsubmit=async e=>{e.preventDefault();if(readOnly||waSendingChats.has(id))return;const textarea=$('#wa-send-text'),button=$('#wa-send-button'),text=textarea.value.trim();if(!text)return;let request=waSendRequests.get(id);if(!request||request.text!==text){request={text,requestId:uid()};waSendRequests.set(id,request)}waSendingChats.add(id);button.disabled=true;textarea.disabled=true;try{const result=await api('/whatsapp/chats/send','POST',{chatId:id,text,requestId:request.requestId});if(result.status!=='Accepted')throw Error('Send was not confirmed. Your draft has been kept.');waSendRequests.delete(id);waFinishReply(id,text,textarea);await waLoadMessages(true)}catch(err){let confirmed=false;for(let check=0;check<3&&!confirmed;check++){try{const status=await api('/whatsapp/chats/send-status?requestId='+encodeURIComponent(request.requestId));if(status.status==='Accepted'){confirmed=true;waSendRequests.delete(id);waFinishReply(id,text,textarea);await waLoadMessages(true)}}catch{}if(!confirmed&&check<2)await new Promise(resolve=>setTimeout(resolve,800))}if(!confirmed)toast(err.message)}finally{waSendingChats.delete(id);textarea.disabled=!waChatState.wasConnected;button.disabled=!waChatState.wasConnected;if(view==='whatsapp'&&waChatState.selected===id){const live=$('#wa-send-text'),send=$('#wa-send-button');if(live){live.disabled=!waChatState.wasConnected;if(!live.disabled)live.focus?.()}if(send)send.disabled=!waChatState.wasConnected}}};await waLoadMessages(true)}
async function waLoadMessages(scrollToEnd){if(waMessageBusy||!waChatState.selected||view!=='whatsapp')return;waMessageBusy=true;const id=waChatState.selected;try{const result=await api('/whatsapp/chats/messages?chatId='+encodeURIComponent(id)+'&limit='+waChatState.limit);if(view!=='whatsapp'||waChatState.selected!==id||!$('#wa-message-list'))return;const target=$('#wa-message-list'),nearBottom=target.scrollHeight-target.scrollTop-target.clientHeight<70;target.innerHTML=result.messages.map(m=>`<div class="wa-bubble ${m.fromMe?'out':''}">${m.author&&result.chat.isGroup?'<small>'+esc(m.author.split('@')[0])+'</small>':''}${esc(m.text||'['+m.type+' message]')}${m.hasMedia?'<small>Media attachment · view on your phone</small>':''}<small>${esc(waTime(m.timestamp))}${m.fromMe?waReceipt(m):''}</small></div>`).join('')||'<p>No synced messages available for this conversation yet.</p>';if(scrollToEnd||nearBottom)target.scrollTop=target.scrollHeight;const pending=waSendRequests.get(id);if(pending&&!waSendingChats.has(id)){try{const confirmation=await api('/whatsapp/chats/send-status?requestId='+encodeURIComponent(pending.requestId));if(confirmation.status==='Accepted'){waSendRequests.delete(id);waFinishReply(id,pending.text,null);const notice=$('#toast');if(notice&&/Message delivery could not be confirmed|uncertain send result/.test(notice.textContent||''))notice.hidden=true}}catch{}}if(view!=='whatsapp'||waChatState.selected!==id)return;const readOnly=result.chat.isGroup||result.chat.isReadOnly||waSendingChats.has(id);$('#wa-send-text').disabled=readOnly;$('#wa-send-button').disabled=readOnly}catch(e){if(view==='whatsapp'&&waChatState.selected===id&&$('#wa-message-list'))$('#wa-message-list').textContent=e.message}finally{waMessageBusy=false}}
setInterval(()=>{if(me?.role==='client'&&view==='whatsapp'&&document.visibilityState!=='hidden')waRefreshConnection(false,false)},5000);

function waFinishReply(id,text,submitted){if(submitted&&submitted.value.trim()===text)submitted.value='';if((waDrafts.get(id)||'').trim()===text)waDrafts.delete(id);if(view!=='whatsapp'||waChatState.selected!==id)return;const live=$('#wa-send-text');if(live&&live.value.trim()===text){live.value='';live.style&&(live.style.height='42px')} }
